package com.cxy.workbench;
import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.*;
import android.os.Build;
import android.os.Bundle;
import android.util.*;
import android.widget.RemoteViews;
import org.json.*;
import java.util.*;

/** One immutable, density-aware bitmap per changed visual state. Full RemoteViews updates only. */
final class BitmapCards {
 static final LruCache<String,Bitmap> CACHE=new LruCache<String,Bitmap>(16*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getAllocationByteCount();}};
 static final class AndroidSurface implements CardPainter.Surface {
  final Canvas canvas;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.SUBPIXEL_TEXT_FLAG);
  AndroidSurface(Canvas c){canvas=c;}
  void color(int c){paint.setShader(null);paint.setColor(c);paint.setStyle(Paint.Style.FILL);paint.setStrokeCap(Paint.Cap.ROUND);}
  public void rect(float x,float y,float w,float h,float r,int c){color(c);canvas.drawRoundRect(x,y,x+Math.max(0,w),y+Math.max(0,h),r,r,paint);}
  public void line(float a,float b,float c,float d,float width,int color){color(color);paint.setStrokeWidth(width);canvas.drawLine(a,b,c,d,paint);}
  public void circle(float x,float y,float r,int c){color(c);canvas.drawCircle(x,y,r,paint);}
  public void glow(float x,float y,float r,int c){color(c);paint.setShader(new RadialGradient(x,y,r,new int[]{c,c&0x00ffffff},new float[]{0,1},Shader.TileMode.CLAMP));paint.setAlpha(255);canvas.drawCircle(x,y,r,paint);paint.setShader(null);}
  public void arc(float x,float y,float r,float stroke,float start,float sweep,int c){color(c);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(stroke);paint.setStrokeCap(Paint.Cap.BUTT);canvas.drawArc(x-r,y-r,x+r,y+r,start,sweep,false,paint);}
  void font(float size,boolean bold){paint.setTextSize(size);paint.setTypeface(bold?Typeface.create("sans-serif",Typeface.BOLD):Typeface.create("sans-serif",Typeface.NORMAL));}
  public void text(String s,float x,float y,float size,int c,boolean bold){color(c);font(size,bold);canvas.drawText(s==null?"—":s,x,y,paint);}
  public float measure(String s,float size,boolean bold){font(size,bold);return paint.measureText(s==null?"—":s);}
 }
 static int[] pixels(Context c,float w,float h){float density=c.getResources().getDisplayMetrics().density;float pw=Math.max(1,w*density),ph=Math.max(1,h*density);long screen=(long)c.getResources().getDisplayMetrics().widthPixels*c.getResources().getDisplayMetrics().heightPixels;float budget=Math.min(1200000f,Math.max(4096f,screen*.15f));float factor=Math.min(1,(float)Math.sqrt(budget/(pw*ph)));return new int[]{Math.max(1,Math.round(pw*factor)),Math.max(1,Math.round(ph*factor))};}
 static boolean dark(Context c){return (c.getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;}
 static Bitmap device(Context c,JSONObject data,String kind,long now,float w,float h){
  int[] size=pixels(c,w,h);JSONObject d=kind.equals("gateway")?data==null?null:data.optJSONObject("gateway"):DeviceText.sample(data,kind);JSONObject linux=DeviceText.sample(data,"linux");String relevant=kind.equals("overview")?String.valueOf(data):String.valueOf(d)+(kind.equals("gateway")?String.valueOf(linux):"");if(kind.equals("overview"))for(String id:new String[]{"mac","winpc","linux","phone"}){JSONObject sample=DeviceText.sample(data,id);relevant+="|"+WidgetNetwork.lanDirect(sample,now)+"|"+WidgetNetwork.privateLabel(sample,now)+"|"+DeviceText.hardwareFresh(sample,now);}String key="d|"+kind+"|"+size[0]+"|"+size[1]+"|"+dark(c)+"|"+relevant.hashCode()+"|"+DeviceText.hardwareFresh(d,now)+"|"+WidgetNetwork.lanDirect(d,now)+"|"+WidgetNetwork.privateLabel(d,now);
  synchronized(CACHE){Bitmap cached=CACHE.get(key);if(cached!=null)return cached;Bitmap bitmap=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.scale(size[0]/w,size[1]/h);MobileDevicePainter.draw(new AndroidSurface(canvas),data,kind,now,w,h,dark(c));CACHE.put(key,bitmap);return bitmap;}
 }
 static Bitmap action(Context c,JSONObject data,int group,String mode,int page,String selected,float w,float h){int[] size=pixels(c,w,h);String relevant=data==null?"":String.valueOf(data.optJSONArray("items"))+String.valueOf(data.optJSONArray("calendarEvents"))+data.optString("generatedAt","");String key="a|"+size[0]+"|"+size[1]+"|"+dark(c)+"|"+relevant.hashCode()+"|"+group+"|"+mode+"|"+page+"|"+selected;synchronized(CACHE){Bitmap old=CACHE.get(key);if(old!=null)return old;Bitmap b=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.scale(size[0]/w,size[1]/h);MobileActionPainter.draw(new AndroidSurface(canvas),data,group,mode,page,selected,w,h,dark(c));CACHE.put(key,b);return b;}}
 static PendingIntent actionIntent(Context c,int id,ActionPainter.Hit hit,int serial){Intent intent=new Intent(c,ActionWidget.class).setAction("com.cxy.workbench.ACTION_CARD").putExtra("widgetId",id).putExtra("operation",hit.action).putExtra("value",hit.value);intent.setData(android.net.Uri.parse("cxy-workbench://widget/"+id+"/"+android.net.Uri.encode(hit.action)+"/"+android.net.Uri.encode(hit.value)));return PendingIntent.getBroadcast(c,20000+serial,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static RemoteViews actionViews(Context c,AppWidgetManager manager,int id,JSONObject data){int group=Math.floorMod(Store.prefs(c).getInt("widget-page-"+id,0),5),page=Store.prefs(c).getInt("widget-action-page-"+id,0);String mode=Store.prefs(c).getString("widget-mode-"+id,"ring"),selected=Store.prefs(c).getString("widget-selected-"+id,"");Map<SizeF,RemoteViews> variants=new LinkedHashMap<>();for(SizeF size:sizes(c,manager,id,360,400)){RemoteViews v=base(c,action(c,data,group,mode,page,selected,size.getWidth(),size.getHeight()),"行动台，"+ActionPainter.GROUPS[group]+"，点击查看详情");v.setOnClickPendingIntent(R.id.card_root,Widgets.activity(c,"actions"));if(Build.VERSION.SDK_INT>=31){List<ActionPainter.Hit> hits=MobileActionPainter.draw(new RecordingSurface(),data,group,mode,page,selected,size.getWidth(),size.getHeight(),dark(c));int serial=0;for(ActionPainter.Hit hit:hits){v.addView(R.id.card_hits,hit(c,hit.x,hit.y,hit.w,hit.h,actionIntent(c,id,hit,serial++),hit.action.equals("select")?"展开或收起事项":"行动台"+hit.action));}}variants.put(size,v);}return Build.VERSION.SDK_INT>=31?new RemoteViews(variants):variants.values().iterator().next();}
 static final class RecordingSurface implements CardPainter.Surface {final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);public void rect(float x,float y,float w,float h,float r,int c){}public void line(float a,float b,float c,float d,float w,int col){}public void circle(float x,float y,float r,int c){}public void glow(float x,float y,float r,int c){}public void arc(float x,float y,float r,float w,float a,float b,int c){}public void text(String s,float x,float y,float sz,int col,boolean b){}public float measure(String s,float size,boolean bold){p.setTextSize(size);p.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);return p.measureText(s==null?"—":s);}}
 static List<SizeF> sizes(Context c,AppWidgetManager manager,int id,float defaultW,float defaultH){Bundle options=manager.getAppWidgetOptions(id);android.appwidget.AppWidgetProviderInfo info=manager.getAppWidgetInfo(id);android.graphics.Rect pad=info==null?new android.graphics.Rect():android.appwidget.AppWidgetHostView.getDefaultPaddingForWidget(c,info.provider,null);float density=c.getResources().getDisplayMetrics().density,pw=(pad.left+pad.right)/density,ph=(pad.top+pad.bottom)/density;ArrayList<SizeF> list=Build.VERSION.SDK_INT>=31?options.getParcelableArrayList(AppWidgetManager.OPTION_APPWIDGET_SIZES):null;ArrayList<SizeF> selected=new ArrayList<>();if(list!=null)for(SizeF s:list){SizeF content=new SizeF(Math.max(1,(float)Math.floor(s.getWidth()-pw)),Math.max(1,(float)Math.floor(s.getHeight()-ph)));if(!selected.contains(content)){selected.add(content);if(selected.size()==8)break;}}if(!selected.isEmpty())return selected;boolean portrait=c.getResources().getConfiguration().orientation!=Configuration.ORIENTATION_LANDSCAPE;float w=options.getInt(portrait?AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH:AppWidgetManager.OPTION_APPWIDGET_MAX_WIDTH,(int)defaultW),h=options.getInt(portrait?AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT:AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,(int)defaultH);return Collections.singletonList(new SizeF(Math.max(180,w-pw),Math.max(140,h-ph)));}
 static RemoteViews base(Context c,Bitmap image,String accessibility){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.bitmap_widget);v.setImageViewBitmap(R.id.card_bitmap,image);v.setContentDescription(R.id.card_bitmap,accessibility);return v;}
 static RemoteViews hit(Context c,float x,float y,float w,float h,PendingIntent click,String label){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.bitmap_hit);if(Build.VERSION.SDK_INT>=31){v.setViewLayoutWidth(R.id.card_hit,w,TypedValue.COMPLEX_UNIT_DIP);v.setViewLayoutHeight(R.id.card_hit,h,TypedValue.COMPLEX_UNIT_DIP);v.setViewLayoutMargin(R.id.card_hit,RemoteViews.MARGIN_LEFT,x,TypedValue.COMPLEX_UNIT_DIP);v.setViewLayoutMargin(R.id.card_hit,RemoteViews.MARGIN_TOP,y,TypedValue.COMPLEX_UNIT_DIP);}v.setContentDescription(R.id.card_hit,label);v.setOnClickPendingIntent(R.id.card_hit,click);return v;}
 static RemoteViews deviceViews(Context c,AppWidgetManager manager,int id,int kind,JSONObject data){Map<SizeF,RemoteViews> variants=new LinkedHashMap<>();for(SizeF s:sizes(c,manager,id,360,170)){Bitmap image=device(c,data,DeviceWidgets.KINDS[kind],System.currentTimeMillis(),s.getWidth(),s.getHeight());RemoteViews v=base(c,image,DeviceWidgets.TITLES[kind]+"，点击打开详情");Intent open=new Intent(c,MainActivity.class).putExtra("tab","devices").putExtra("device",DeviceWidgets.KINDS[kind]).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);v.setOnClickPendingIntent(R.id.card_root,PendingIntent.getActivity(c,800+kind,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));if(Build.VERSION.SDK_INT>=31){Intent refresh=new Intent(c,DeviceWidgets.PROVIDERS[kind]).setAction("com.cxy.workbench.REFRESH");PendingIntent pi=PendingIntent.getBroadcast(c,500+kind,refresh,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.addView(R.id.card_hits,hit(c,s.getWidth()-62,s.getHeight()-40,40,40,pi,"刷新设备状态"));}variants.put(s,v);}return Build.VERSION.SDK_INT>=31?new RemoteViews(variants):variants.values().iterator().next();}
}
